# region: render
def render(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: fold
def fold(xs, factor=2):
    return [v * factor for v in xs]

# region: shape
def shape(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(sift(shape(fold(render(raw)))))

